<?php function cb_tabbar(string $on): string { $t = ['content_plan' => t('إنشاء المحتوى'), 'content_bank' => t('مخزون المحتوى')]; $h = '<nav class="flex gap-1 border-b border-ink-200 mb-5 overflow-x-auto text-sm">'; foreach ($t as $k => $l) { if (page_permission($k) !== null && !can(page_permission($k))) continue; $h .= '<a href="' . e(url($k)) . '" class="whitespace-nowrap px-3 py-2 -mb-px border-b-2 ' . ($k === $on ? 'border-brand-600 text-brand-700 font-semibold' : 'border-transparent text-ink-500 hover:text-ink-900') . '">' . e($l) . '</a>'; } return $h . '</nav>'; } ?>
